var i=`1172-huaraches`;var n=`world-1172`;var t=`MX`;var s=`central-america-caribbean`;var o=8;var r=52;var l={en:`Huaraches`,ua:`Уарачес`};var d={en:`Huaraches is a dish from Mexico prepared with masa harina, ground beef, canned black beans, queso fresco. This is a home-scale version with measured ingredients in the individual steps where they are used. Canned black beans replace prepared refried beans.`,ua:`Уарачес, страва кухні країни Мексика, яку готують із таких продуктів: маса харіна, яловичий фарш, консервована чорна квасоля, кесо фреско. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Консервована чорна квасоля замінює готову пересмажену.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`masa-harina`,460,`g`],[`water`,355,`ml`],[`table-salt`,5,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`canola-oil`,65,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`ground-beef`,320,`g`],[`canola-oil`,20,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`canned-black-beans`,320,`g`],[`queso-fresco`,170,`g`],[`lettuce`,150,`g`],[`red-salsa`,130,`g`]]}];var h={slug:i,id:n,country:`MX`,region:s,servings:8,minutes:52,title:l,text:d,steps:u};export{t as country,h as default,n as id,r as minutes,s as region,o as servings,i as slug,u as steps,d as text,l as title};